<template>
  <div class="group-navigator">
    <div class="nav-header">
      <q-input
        v-model="search"
        dense
        outlined
        :placeholder="$t('search_group')"
      >
        <template v-slot:prepend><q-icon name="search" /></template>
      </q-input>
      <q-btn
        color="primary"
        icon="add"
        :label="$t('new')"
        class="full-width q-mt-sm"
        dense
        unelevated
        no-caps
        @click="showCreateDialog = true"
      />
    </div>
    <q-scroll-area class="nav-list">
      <!-- Loading skeleton -->
      <q-list v-if="loading">
        <q-item v-for="i in 5" :key="'skeleton-' + i">
          <q-item-section avatar>
            <q-skeleton type="QAvatar" />
          </q-item-section>
          <q-item-section>
            <q-skeleton type="text" />
          </q-item-section>
        </q-item>
      </q-list>

      <!-- Empty state when no groups -->
      <div v-else-if="!groups.length" class="empty-state">
        <q-icon name="group_off" size="64px" color="grey-5" class="q-mb-md" />
        <div class="text-subtitle1 text-grey-7 q-mb-sm">
          {{ $t('no_record_found') }}
        </div>
      </div>

      <!-- Group list items -->
      <q-list v-else class="nav-list-inner">
        <q-item
          v-for="group in filteredGroups"
          :key="group.group_id"
          clickable
          :active="selectedGroupId === group.group_id"
          class="group-nav-item"
          @click="$emit('group-selected', group)"
        >
          <q-item-section avatar class="nav-item-avatar">
            <q-icon name="group" size="18px" color="grey-7" />
          </q-item-section>
          <q-item-section class="nav-item-label-section">
            <q-item-label class="nav-item-label" lines="1">
              {{ group.group_name }}
              <q-tooltip
                anchor="top middle"
                self="bottom middle"
                :delay="400"
                max-width="280px"
              >
                {{ group.group_name }}
              </q-tooltip>
            </q-item-label>
          </q-item-section>
          <q-item-section side class="nav-item-action">
            <q-btn
              flat
              dense
              round
              icon="more_vert"
              size="sm"
              @click.stop
            >
              <q-menu
                auto-close
                transition-show="jump-down"
                transition-hide="jump-up"
              >
                <q-list dense style="min-width: 150px">
                  <q-item clickable @click="$emit('edit-group', group)">
                    <q-item-section avatar>
                      <q-icon name="edit" size="xs" />
                    </q-item-section>
                    <q-item-section>{{ $t('edit') }}</q-item-section>
                  </q-item>
                  <q-item clickable @click="$emit('view-access-control', group)">
                    <q-item-section avatar>
                      <q-icon name="admin_panel_settings" size="xs" />
                    </q-item-section>
                    <q-item-section>{{ $t('view_access_control') }}</q-item-section>
                  </q-item>
                  <q-separator />
                  <q-item clickable @click="confirmDeleteGroup(group)">
                    <q-item-section avatar>
                      <q-icon name="delete" size="xs" color="negative" />
                    </q-item-section>
                    <q-item-section>
                      <span class="text-red">{{ $t('delete') }}</span>
                    </q-item-section>
                  </q-item>
                </q-list>
              </q-menu>
            </q-btn>
          </q-item-section>
        </q-item>
      </q-list>
    </q-scroll-area>
  </div>

  <!-- Create New Group Dialog -->
  <q-dialog
    v-model="showCreateDialog"
    persistent
    @keydown.esc="showCreateDialog = false"
  >
    <CreateGroup />
  </q-dialog>

  <!-- Edit Group Dialog -->
  <q-dialog
    v-model="showEditDialog"
    persistent
    @keydown.esc="showEditDialog = false"
  >
    <CreateGroup
      :is_edit="true"
      :name="editGroupName"
      :id="editGroupId"
    />
  </q-dialog>

  <!-- Delete Confirmation Dialog -->
  <q-dialog v-model="showDeleteConfirm" persistent>
    <q-card style="min-width: 400px">
      <q-card-section class="bg-primary text-white q-pa-md">
        <div class="row items-center">
          <q-icon name="warning" size="sm" color="white" class="q-mr-sm" />
          <div class="text-h6">{{ $t('warning_item_will_be_deleted') }}</div>
        </div>
      </q-card-section>

      <q-card-section class="q-pt-md">
        <p>{{ $t('msg_delete') }}</p>
      </q-card-section>

      <q-card-actions align="right" class="q-pa-md">
        <f-btn appearance="cancel" :label="$t('cancel')" v-close-popup />
        <f-btn
          appearance="negative"
          :label="$t('delete')"
          @click="handleDeleteGroup"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import CreateGroup from './CreateGroup.vue';

export default defineComponent({
  name: 'GroupNavigator',

  components: {
    CreateGroup,
  },

  props: {
    groups: {
      type: Array as PropType<any[]>,
      required: true,
    },
    selectedGroupId: {
      type: String as PropType<string | null>,
      default: null,
    },
    loading: {
      type: Boolean,
      default: false,
    },
  },

  emits: ['group-selected', 'edit-group', 'view-access-control', 'delete-group', 'group-edited'],

  data() {
    return {
      search: '',
      showCreateDialog: false,
      showEditDialog: false,
      showDeleteConfirm: false,
      groupToDelete: null as any,
      editGroupName: '',
      editGroupId: '',
    };
  },

  computed: {
    filteredGroups(): any[] {
      if (!this.search) return this.groups;
      const query = this.search.toLowerCase();
      return this.groups.filter(
        (g: any) =>
          g.group_name?.toLowerCase().includes(query) ||
          g.description?.toLowerCase().includes(query),
      );
    },
  },

  mounted() {
    document.addEventListener('group_added', this.handleGroupAdded);
    document.addEventListener('group_edited', this.handleGroupEdited);
  },

  beforeUnmount() {
    document.removeEventListener('group_added', this.handleGroupAdded);
    document.removeEventListener('group_edited', this.handleGroupEdited);
  },

  methods: {
    handleGroupAdded() {
      this.showCreateDialog = false;
    },

    handleGroupEdited() {
      this.showEditDialog = false;
      this.$emit('group-edited');
    },

    openEditDialog(group: any) {
      this.editGroupName = group.group_name;
      this.editGroupId = group.group_id;
      this.showEditDialog = true;
    },

    confirmDeleteGroup(group: any) {
      this.groupToDelete = group;
      this.showDeleteConfirm = true;
    },

    handleDeleteGroup() {
      if (!this.groupToDelete) return;
      this.$emit('delete-group', this.groupToDelete);
      this.showDeleteConfirm = false;
      this.groupToDelete = null;
    },
  },
});
</script>

